def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target = 0.25 * bins
    score = -np.square(remaining - target)
    return np.where(remaining >= 0, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    ratio = remaining / (bins + 1e-8)
    score = -np.square(ratio - 0.25)
    return np.where(remaining >= 0, score, -np.inf)
